:root {
--radius-none: 0;
--radius-sm: 4px;      /* 개별 구매 카드 썸네일 */
--radius-md: 8px;      /* 버튼·로그인·「참여하기」·검색창·카테고리 타일 */
--radius-lg: 12px;     /* 구독 CTA·구독 비교 카드 */
--radius-xl: 16px;     /* 바텀시트·모달 (추정) */
--radius-full: 9999px; /* 원형 아이콘 버튼 (코드상 10000px) */
--shadow-none: none;
--shadow-sm: 0px 2px 6px 0px rgba(0,0,0,.04), 0px 2px 1px 0px rgba(0,0,0,.04);        /* --vb-e-1 · 칩·작은 버튼 */
--shadow-md: 0px 5px 8px -1px rgba(0,0,0,.06), 0px 1px 4px 0px rgba(0,0,0,.04);       /* --vb-e-2 · 떠 있는 구독 바·비교 카드 */
--shadow-lg: 0px 20px 20px -4px rgba(0,0,0,.10), 0px 12px 12px -2px rgba(0,0,0,.04), 0px 2px 7px 1px rgba(0,0,0,.04);  /* --vb-e-3 · 드롭다운·카테고리 메뉴 */
--shadow-xl: 0px 28px 28px -4px rgba(0,0,0,.16), 0px 16px 16px -2px rgba(0,0,0,.06), 0px 2px 8px 1px rgba(0,0,0,.04);  /* --vb-e-4 · 모달 */
--duration-fast: 160ms;   /* 버튼·링크 상태 레이어 (가장 많이 쓰임) */
--duration-base: 200ms;   /* 로고 링크 opacity */
--duration-slow: 300ms;
--ease-out: cubic-bezier(0.5, 1, 0.89, 1);      /* easeOutQuad — 기본 */
--ease-in-out: cubic-bezier(0.25, 0.46, 0.45, 0.94);
--ease-expo: cubic-bezier(0.16, 1, 0.3, 1);     /* 캐러셀·패널 */
}
:root {
  /* Primary - Vibrant orange (dark: primary=orange 60, onViewPrimary=orange 65) */
  --color-primary-50:  #1C1008;  /* orange 10 · primaryContainer */
  --color-primary-100: #371A07;  /* orange 15 · orangeMuted */
  --color-primary-200: #652300;  /* orange 25 */
  --color-primary-300: #792900;  /* orange 30 · orangeSoft */
  --color-primary-400: #FF8D57;  /* orange 70 · 구독 CTA 그라데이션 윗단 */
  --color-primary-500: #FF5D00;  /* orange 60 · primary (기본) */
  --color-primary-600: #FF7430;  /* orange 65 · onViewPrimary (다크 면 위 오렌지 글자) */
  --color-primary-700: #FF8D57;  /* orange 70 · orangeContrast */
  --color-primary-800: #FCCFB9;  /* orange 85 */
  --color-primary-900: #FCF5F1;  /* orange 95 · orangeInverse · 헤드라인 그라데이션 끝 */

  /* Secondary - 개별 구매(masterColor) 바이올렛 */
  --color-secondary-50:  #24063C;  /* violet 10 */
  --color-secondary-300: #55038F;  /* violet 25 · violetSoft */
  --color-secondary-500: #B452FE;  /* violet 55 · violetVibrant */
  --color-secondary-700: #D291FE;  /* violet 70 · violetContrast */

  /* Neutral (반전) */
  --color-neutral-0:    #0C0C0C;  /* neutral 5 · background */
  --color-neutral-50:   #171717;  /* neutral 10 · surface2 · neutralMuted */
  --color-neutral-100:  #2B2B2B;  /* neutral 20 · neutralSoft */
  --color-neutral-300:  #5B5B5B;  /* neutral 40 · surface4 */
  --color-neutral-500:  #747474;  /* neutral 50 · onView3 */
  --color-neutral-700:  #ABABAB;  /* neutral 70 */
  --color-neutral-900:  #F3F3F3;  /* neutral 95 · onView1 */
  --color-neutral-1000: #FFFFFF;

  /* Semantic */
  --color-success-bg: #071309;  /* green 10 · successContainer */
  --color-success-fg: #0CA954;  /* green 60 · onViewSuccess */
  --color-warning-bg: #1A1308;  /* yellow 10 */
  --color-warning-fg: #FCA50E;  /* yellow 75 */
  --color-error-bg:   #200D08;  /* red 10 */
  --color-error-fg:   #FD5B59;  /* red 60 · onViewError (할인율) */
  --color-info-bg:    #0E142A;  /* blue 10 */
  --color-info-fg:    #788BFB;  /* blue 60 · onViewInformative */

  /* Surface */
  --bg-base:     #0C0C0C;    /* background (theme-color 도 #0C0C0C) */
  --bg-subtle:   #FFFFFF0D;  /* surface1 · whiteAlpha 5 */
  --bg-elevated: #171717;    /* surface2 */
  --bg-overlay:  #000000;    /* surface3 · globalBlack */

  /* Text */
  --text-primary:    #F3F3F3;    /* onView1 */
  --text-secondary:  #F3F3F3A6;  /* onView2 */
  --text-tertiary:   #747474;    /* onView3 */
  --text-on-primary: #FFFFFF;
  --text-disabled:   #FFFFFF26;  /* (추정) disable = whiteAlpha 15 */

  /* Border */
  --border-default: #FFFFFF26;  /* outline2 */
  --border-subtle:  #FFFFFF14;  /* outline1 */
  --border-strong:  #F3F3F3;    /* outlineNeutral */
  --border-focus:   #FFFFFF26;  /* outlineFocus */

  --overlay-hover:  0.025;
  --overlay-active: 0.075;
  --text-active:    0.6;
}

[data-theme="light"] {
  --color-primary-50:  #FCF5F1;
  --color-primary-100: #FBE2D7;
  --color-primary-200: #FCCFB9;
  --color-primary-300: #FDBA9A;
  --color-primary-400: #FF8D57;
  --color-primary-500: #FF5D00;
  --color-primary-600: #E35200;
  --color-primary-700: #CD4900;
  --color-primary-800: #A33800;
  --color-primary-900: #371A07;
  --color-secondary-50: #F8F1FC; --color-secondary-300: #E2B8FD; --color-secondary-500: #A839FD; --color-secondary-700: #8A04E4;
  --color-neutral-0: #FFFFFF; --color-neutral-50: #F3F3F3; --color-neutral-100: #E5E5E5; --color-neutral-300: #C7C7C7;
  --color-neutral-500: #949494; --color-neutral-700: #5B5B5B; --color-neutral-900: #0C0C0C; --color-neutral-1000: #000000;
  --color-success-bg: #DBFCE1; --color-success-fg: #078641;
  --color-warning-bg: #FCF2E7; --color-warning-fg: #B27307;
  --color-error-bg:   #FCF1F0; --color-error-fg:   #E30F32;
  --color-info-bg:    #F3F3FC; --color-info-fg:    #376DFA;
  --bg-base: #FFFFFF; --bg-subtle: #00000008; --bg-elevated: #FFFFFF; --bg-overlay: #FFFFFF;
  --text-primary: #0C0C0C; --text-secondary: #373737CC; --text-tertiary: #949494; --text-on-primary: #FFFFFF; --text-disabled: #C7C7C7;
  --border-default: #0000001A; --border-subtle: #0000000D; --border-strong: #0C0C0C; --border-focus: #00000033;
}




.c1-btn { position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 38px; padding: 0 16px; border: 0; border-radius: var(--radius-md);
  font: 700 14px/18px Pretendard, sans-serif; letter-spacing: -0.012em; cursor: pointer; overflow: hidden;
  transition: opacity 160ms cubic-bezier(0.5,1,0.89,1); }
.c1-btn::after { content: ""; position: absolute; inset: 0; background: #FFF; opacity: 0; transition: opacity 160ms cubic-bezier(0.5,1,0.89,1); }
.c1-btn:hover::after { opacity: var(--overlay-hover); }
.c1-btn:active::after { opacity: var(--overlay-active); }
.c1-btn:disabled { background: var(--border-default); color: var(--text-disabled); cursor: not-allowed; }
.c1-btn:disabled::after { opacity: 0; }
.c1-btn.is-loading { color: transparent; pointer-events: none; }
.c1-btn.is-loading::before { content: ""; position: absolute; width: 16px; height: 16px; border-radius: 50%;
  border: 2px solid currentColor; border-color: var(--text-on-primary) transparent var(--text-on-primary) var(--text-on-primary); animation: c1-spin .8s linear infinite; }
@keyframes c1-spin { to { transform: rotate(360deg); } }

/* Primary — 구독 CTA */
.c1-btn--primary { height: 50px; padding: 0 32px; border-radius: var(--radius-lg); font-size: 16px; line-height: 20px;
  color: var(--text-on-primary); background: linear-gradient(0deg, var(--color-primary-500) 40%, var(--color-primary-400) 100%); }
/* Secondary — 「참여하기」·「로그인」 회색 면 */
.c1-btn--secondary { background: var(--bg-subtle); color: var(--text-primary); }
/* Ghost — 「포함된 모든 클래스 보기 >」 */
.c1-btn--ghost { background: transparent; color: var(--text-primary); font-weight: 500; padding: 0 4px; border-radius: var(--radius-sm); }
.c1-btn--ghost:active { opacity: var(--text-active); }
/* Danger */
.c1-btn--danger { background: var(--color-error-fg); color: #FFFFFF; }
.c1-search { display: flex; align-items: center; gap: 8px; height: 44px; padding: 0 16px;
  border-radius: var(--radius-md); background: var(--bg-base); box-shadow: inset 0 0 0 1px var(--border-subtle);
  font: 400 14px/18px Pretendard, sans-serif; color: var(--text-primary); }
.c1-search::placeholder { color: var(--text-tertiary); }         /* 「클래스, 크리에이터」 */
.c1-search:focus { outline: none; box-shadow: inset 0 0 0 1px var(--border-focus); }
.c1-search.is-error { box-shadow: inset 0 0 0 1px var(--color-error-fg); }
.c1-search:disabled { background: var(--bg-subtle); color: var(--text-disabled); }
/* 기본형 — 클래스 카드: 테두리·그림자 없음 */
.c1-class { display: flex; flex-direction: column; gap: 4px; }
.c1-class__thumb { aspect-ratio: 16 / 9; border-radius: var(--radius-sm); overflow: hidden; position: relative; background: var(--bg-subtle); }
.c1-class__title { font: 400 14px/18px Pretendard, sans-serif; color: var(--text-primary); margin-top: 8px; }
.c1-class__meta  { font: 400 13px/18px Pretendard, sans-serif; color: var(--text-tertiary); }
.c1-class__price b { color: var(--color-error-fg); font-weight: 600; }   /* 할인율 */
.c1-class__price strong { color: var(--text-primary); font-weight: 700; }
/* 강조형 — CLASS101+ 비교 카드 */
.c1-card--plus { border-radius: var(--radius-lg); color: #FFFFFF;
  background: linear-gradient(180deg, var(--color-primary-500) 0%, #2A1A10 45%, #1C1C1C 100%);
  box-shadow: inset 0 0 0 2px var(--color-primary-500); }
/* Outlined — 라이브 특강 카드 */
.c1-card--outlined { border-radius: var(--radius-md); padding: 8px; background: var(--bg-elevated); box-shadow: inset 0 0 0 1px var(--border-subtle); }
.c1-badge { display: inline-flex; align-items: center; height: 20px; padding: 0 6px; border-radius: var(--radius-sm); font: 700 11px/14px Pretendard, sans-serif; }
.c1-badge--solid   { background: var(--color-error-fg); color: #FFFFFF; }            /* 「● 09.28 라이브」 */
.c1-badge--subtle  { background: var(--color-primary-50); color: var(--color-primary-500); }
.c1-badge--outline { box-shadow: inset 0 0 0 1px var(--border-default); color: var(--text-secondary); }
.c1-badge--new     { background: #FCA50E; color: #0A0703; }                          /* 「NEW」 */
.c1-gnb { height: 72px; display: flex; align-items: center; gap: 16px; padding: 0 40px; background: var(--bg-base); }
.c1-gnb__mode { font: 700 20px/26px Pretendard, sans-serif; letter-spacing: -0.018em; color: var(--color-primary-500); } /* 구독 */
.c1-gnb__mode--tvod { color: var(--color-secondary-500); }                                                               /* 개별 구매 */
.c1-gnb__switch { font: 500 16px/20px Pretendard, sans-serif; color: var(--text-secondary); padding-left: 16px; box-shadow: inset 1px 0 0 var(--border-default); }
.c1-catnav { display: flex; gap: 24px; height: 44px; align-items: center; font: 600 14px/18px Pretendard, sans-serif; }
.c1-catnav a { display: flex; gap: 6px; align-items: center; color: var(--text-primary); }
